import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"Update a Pumpkin Market listing","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/actions/update-pumpkin-market-listing/docs/index.md"},"headers":[],"relativePath":"actions/update-pumpkin-market-listing/docs/index.md","filePath":"actions/update-pumpkin-market-listing/docs/index.md","lastUpdated":1792252155000}`),l={name:`actions/update-pumpkin-market-listing/docs/index.md`},u={id:`update-a-pumpkin-market-listing`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/update-pumpkin-market-listing-v0.0.3`,"aria-label":`Release v0.0.3`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`Update a Pumpkin Market listing `),n(`a`,{class:`header-anchor`,href:`#update-a-pumpkin-market-listing`,"aria-label":`Permalink to “Update a Pumpkin Market listing”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.3`})])]),c[1]||=r(`<p>Use this action to change metadata on a listing that already exists in Pumpkin Market. It’s useful when the listing details need an update independently of a plugin upload. The action doesn’t create listings, read <code>src/info.ts</code>, build or upload a WASM file, or manage screenshots.</p><h2 id="choose-the-listing-and-prepare-its-metadata" tabindex="-1">Choose the listing and prepare its metadata <a class="header-anchor" href="#choose-the-listing-and-prepare-its-metadata" aria-label="Permalink to “Choose the listing and prepare its metadata”">​</a></h2><p>Set exactly one of <code>plugin-name</code> and <code>plugin-id</code>. A name must be an exact match, regardless of capitalization; the action fails if it finds no match or more than one. An ID can be the numeric database ID or the listing’s public ID.</p><p>You can provide metadata in a JSON file, with direct inputs, or with both. The JSON file uses Market field names such as <code>name</code>, <code>sourceLink</code>, and <code>translatedDescriptions</code>. Direct inputs override the matching fields from the file; for example, <code>display-name</code> sets <code>name</code>. The <code>description</code> input updates the <code>en-US</code> description and keeps other translations from the file.</p><p>Blank direct inputs are omitted, so they don’t clear a value already on the listing. If you need to send an explicit empty value for a field that accepts one, put that value in the JSON file. The <a href="/pumpkin-plugins/actions/update-pumpkin-market-listing/README">action README</a> has a workflow example, an example metadata file, and the complete input reference.</p><h2 id="decide-how-much-metadata-to-send" tabindex="-1">Decide how much metadata to send <a class="header-anchor" href="#decide-how-much-metadata-to-send" aria-label="Permalink to “Decide how much metadata to send”">​</a></h2><p><code>update-mode</code> defaults to <code>patch</code>. In this mode, the action sends only the metadata fields you provided. Use it for a focused edit, such as changing the description while leaving other listing details alone.</p><p>Set <code>update-mode: full</code> when you want to provide the complete listing metadata. The action requires all of these fields in the combined metadata before it sends the update: <code>name</code>, <code>category</code>, <code>sourceLink</code>, <code>youtubeVideoUrl</code>, <code>keywords</code>, <code>translatedDescriptions</code>, <code>isEarlyAccess</code>, and <code>commands</code>. Both modes use Market’s metadata <code>PUT</code> endpoint; <code>patch</code> and <code>full</code> describe which fields the action accepts, not different HTTP methods.</p><p>In a test against an unpublished listing, Market left the existing name and category unchanged when a partial update omitted them. Command row reconciliation and preservation of version or track data on published listings haven’t been confirmed. If your update includes commands or targets a published listing, review the result in Market. See the <a href="/pumpkin-plugins/guides/pumpkin-market-api#partial-and-full-listing-updates">Market API notes</a> for the tested behavior and its limits.</p><h2 id="run-the-action-and-check-the-result" tabindex="-1">Run the action and check the result <a class="header-anchor" href="#run-the-action-and-check-the-result" aria-label="Permalink to “Run the action and check the result”">​</a></h2><p>Provide an API token that can update listing metadata. The minimum token scope hasn’t been established; the <a href="/pumpkin-plugins/guides/pumpkin-market-api#updating-listing-metadata">Market API notes</a> describe the token behavior that has been tested. <code>api-url</code> defaults to <code>https://market.pumpkinmc.org</code>; set it only when you use a different Market instance. For a complete workflow example, see the <a href="/pumpkin-plugins/actions/update-pumpkin-market-listing/README">action README</a>.</p><p>After Market accepts the update, the action reports <code>status: success</code> and sets <code>listing-id</code> and <code>listing-name</code> to the resolved database ID and canonical listing name. If lookup, validation, or the Market update fails, the workflow step fails before it writes success outputs.</p>`,12)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};